describe('Notification Filtering by Type', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should filter notifications by type when a filter button is clicked', () => {
    // Intercept API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.get('[data-testid="load-notifications-btn"]').click();
    cy.wait('@getNotifications');

    // Verify all notifications are loaded
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Click on 'info' filter button
    cy.get('[data-testid="filter-info-btn"]').click();

    // Verify only info notifications are displayed
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="notification-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'info');
    });

    // Click on 'warning' filter button
    cy.get('[data-testid="filter-warning-btn"]').click();

    // Verify only warning notifications are displayed
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="notification-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'warning');
    });

    // Click on 'error' filter button
    cy.get('[data-testid="filter-error-btn"]').click();

    // Verify only error notifications are displayed
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="notification-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'error');
    });
  });

  it('should handle filter with no matching notifications and clear filter', () => {
    // Intercept API call to fetch notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.get('[data-testid="load-notifications-btn"]').click();
    cy.wait('@getNotifications');

    // Click on 'info' filter button
    cy.get('[data-testid="filter-info-btn"]').click();

    // Verify info notifications are displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Click on 'warning' filter button
    cy.get('[data-testid="filter-warning-btn"]').click();

    // Verify warning notifications are displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Click on 'error' filter button
    cy.get('[data-testid="filter-error-btn"]').click();

    // Verify error notifications are displayed
    cy.get('[data-testid="notification-item"]').should('be.visible');

    // Click on 'info' filter button again to show all
    cy.get('[data-testid="filter-info-btn"]').click();

    // Verify all notifications are visible again
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Click on 'clear-filters' button
    cy.get('[data-testid="clear-filters-btn"]').click();

    // Verify all filters are cleared and all notifications are shown
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="filter-info-btn"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-warning-btn"]').should('not.have.class', 'active');
    cy.get('[data-testid="filter-error-btn"]').should('not.have.class', 'active');
  });
});
